// Generate the deployment pins from the reviewed manifests.
//
// The manifests are the review artifact. This tool turns them into the one module the SDK exports; consumers read
// that module instead of copying factory addresses. `--check` compares the generated bytes with the committed file.
//
// Run:  node tools/gen-deployment-pins.mjs --write
//       node tools/gen-deployment-pins.mjs --check
import { existsSync, readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const MANIFESTS = join(ROOT, "deployments");
const HISTORY = join(MANIFESTS, "history");
const OUTPUT = join(ROOT, "engine", "core", "deployments.generated.js");

const addressPattern = /^0x[0-9a-fA-F]{40}$/;
const hashPattern = /^0x[0-9a-fA-F]{64}$/;
const networkPattern = /^[a-z0-9][a-z0-9-]*$/;
const positiveInteger = /^[1-9][0-9]*$/;
const ROLES = ["factory", "cashier", "registry", "implementation"];

function fail(message) {
  throw new Error(message);
}

function walk(dir, out = []) {
  for (const name of readdirSync(dir)) {
    const file = join(dir, name);
    if (statSync(file).isDirectory()) {
      if (name !== "archive" && name !== "history") walk(file, out);
    } else if (name.endsWith(".json")) {
      out.push(file);
    }
  }
  return out;
}

function tx(value, field) {
  if (!value || value.kind !== "hash" || typeof value.value !== "string" || !hashPattern.test(value.value)) {
    fail(`${field} is not a typed hash reference`);
  }
  return { kind: "hash", value: value.value };
}

function normalize(manifest, file) {
  const label = relative(ROOT, file).replaceAll("\\", "/");
  if (manifest.schema !== 2) fail(`${label}: schema is ${JSON.stringify(manifest.schema)}, expected 2`);
  if (manifest.vm !== "evm") fail(`${label}: vm ${JSON.stringify(manifest.vm)} has no generator validator yet`);
  if (typeof manifest.network !== "string" || !networkPattern.test(manifest.network)) fail(`${label}: bad network`);
  if (typeof manifest.chainRef !== "string" || !positiveInteger.test(manifest.chainRef)) fail(`${label}: bad chainRef`);
  if (manifest.caip2 !== `eip155:${manifest.chainRef}`) fail(`${label}: caip2 does not match chainRef`);
  if (!["live", "simulated", "retired"].includes(manifest.status)) fail(`${label}: bad status`);
  if (!manifest.anchor || manifest.anchor.kind !== "block" || !positiveInteger.test(String(manifest.anchor.value))) {
    fail(`${label}: bad anchor`);
  }
  if (!manifest.artifacts || typeof manifest.artifacts !== "object") fail(`${label}: artifacts missing`);

  const artifacts = {};
  for (const role of ROLES) {
    const artifact = manifest.artifacts[role];
    if (!artifact || typeof artifact !== "object") fail(`${label}: artifacts.${role} missing`);
    if (artifact.role !== role || artifact.kind !== "contract" || artifact.addressFormat !== "hex-20") {
      fail(`${label}: artifacts.${role} has the wrong shape`);
    }
    if (!addressPattern.test(artifact.address || "")) fail(`${label}: artifacts.${role}.address is not an address`);
    artifacts[role] = {
      role,
      kind: "contract",
      address: artifact.address,
      addressFormat: "hex-20",
      ...(artifact.codeHash ? { codeHash: artifact.codeHash, hashKind: artifact.hashKind } : {}),
      tx: tx(artifact.tx, `${label}: artifacts.${role}.tx`),
    };
    if ((role === "factory" || role === "implementation") &&
        (!hashPattern.test(artifact.codeHash || "") || artifact.hashKind !== "keccak256")) {
      fail(`${label}: artifacts.${role} has no keccak code hash`);
    }
  }

  const escrow = {
    address: artifacts.factory.address,
    mode: manifest.status === "live" ? "live" : null,
    deploymentBlock: Number(manifest.anchor.value),
    cashier: artifacts.cashier.address,
    registry: artifacts.registry.address,
    implementationCodeHash: artifacts.implementation.codeHash,
  };

  return {
    vm: manifest.vm,
    network: manifest.network,
    caip2: manifest.caip2,
    chainRef: manifest.chainRef,
    status: manifest.status,
    release: {
      tag: manifest.release?.tag ?? null,
      commit: manifest.release?.commit ?? null,
      toolchain: manifest.release?.toolchain ?? null,
      deployedAt: manifest.release?.deployedAt ?? null,
    },
    anchor: { kind: "block", value: String(manifest.anchor.value) },
    artifacts,
    escrow,
    knownFactoryCodes: [artifacts.factory.codeHash.toLowerCase()],
  };
}

function normalizeHistory(manifest, file) {
  const label = relative(ROOT, file).replaceAll("\\", "/");
  if (manifest.schema !== 1) fail(`${label}: history schema is ${JSON.stringify(manifest.schema)}, expected 1`);
  if (manifest.vm !== "evm") fail(`${label}: history vm ${JSON.stringify(manifest.vm)} has no validator yet`);
  if (typeof manifest.network !== "string" || !networkPattern.test(manifest.network)) fail(`${label}: bad network`);
  if (typeof manifest.chainRef !== "string" || !positiveInteger.test(manifest.chainRef)) fail(`${label}: bad chainRef`);
  if (manifest.caip2 !== `eip155:${manifest.chainRef}`) fail(`${label}: caip2 does not match chainRef`);
  if (!Array.isArray(manifest.factories) || manifest.factories.length === 0) fail(`${label}: factories is empty`);

  const seen = new Set();
  const factories = manifest.factories.map((entry, index) => {
    if (!entry || typeof entry !== "object" || Array.isArray(entry)) fail(`${label}: factories[${index}] is not an object`);
    if (!addressPattern.test(entry.address || "")) fail(`${label}: factories[${index}].address is not an address`);
    const address = entry.address.toLowerCase();
    if (seen.has(address)) fail(`${label}: duplicate factory ${entry.address}`);
    seen.add(address);
    const block = Number(entry.deploymentBlock);
    if (!Number.isSafeInteger(block) || block <= 0) fail(`${label}: factories[${index}].deploymentBlock is not a positive integer`);
    const tag = entry.release && entry.release.tag;
    if (typeof tag !== "string" || !tag.trim()) fail(`${label}: factories[${index}].release.tag is empty`);
    return { address: entry.address, deploymentBlock: block, release: { tag } };
  });
  return { network: manifest.network, factories };
}

function readHistoryFiles() {
  if (!existsSync(HISTORY)) return [];
  const files = [];
  const visit = (dir) => {
    for (const name of readdirSync(dir)) {
      const file = join(dir, name);
      if (statSync(file).isDirectory()) visit(file);
      else if (name.endsWith(".json")) files.push(file);
    }
  };
  visit(HISTORY);
  return files.sort();
}

function generate() {
  const entries = walk(MANIFESTS).sort();
  if (!entries.length) fail("no deployment manifests under deployments/");
  const deployments = {};
  const caip2s = new Map();
  for (const file of entries) {
    const manifest = JSON.parse(readFileSync(file, "utf8"));
    const normalized = normalize(manifest, file);
    if (deployments[normalized.network]) fail(`duplicate network ${normalized.network}`);
    if (caip2s.has(normalized.caip2)) fail(`caip2 ${normalized.caip2} is also ${caip2s.get(normalized.caip2)}`);
    caip2s.set(normalized.caip2, normalized.network);
    deployments[normalized.network] = normalized;
  }
  const data = Object.fromEntries(Object.entries(deployments).sort(([a], [b]) => a.localeCompare(b)));
  const history = {};
  for (const file of readHistoryFiles()) {
    const normalized = normalizeHistory(JSON.parse(readFileSync(file, "utf8")), file);
    if (!deployments[normalized.network]) fail(`history network ${normalized.network} has no deployment manifest`);
    // HISTORY IS MAINNET ONLY. A development chain replaces its factory on every switch; a retired entry there
    // would make recovery search addresses no user should depend on. Add mainnet chain ids here when they ship.
    if (normalized.chainRef !== "42161") {
      fail(`${normalized.network}: factory history is mainnet-only (chain 42161)`);
    }
    if (history[normalized.network]) fail(`duplicate history for ${normalized.network}`);
    history[normalized.network] = normalized.factories;
  }
  const factoryHistory = {};
  for (const [network, pin] of Object.entries(data)) {
    const current = {
      address: pin.escrow.address,
      deploymentBlock: pin.escrow.deploymentBlock,
      release: pin.release,
      status: "live",
    };
    const previous = (history[network] || []).map((entry) => ({ ...entry, status: "retired" }));
    if (previous.some((entry) => entry.address.toLowerCase() === current.address.toLowerCase())) {
      fail(`${network}: the current factory is also in history`);
    }
    factoryHistory[network] = [...previous, current].sort((a, b) => a.deploymentBlock - b.deploymentBlock);
  }
  return `// GENERATED FILE - do not edit. Run: node tools/gen-deployment-pins.mjs --write
// Source: deployments/<vm>/<network>.json, copied from the reviewed contract release manifest.
// Factory history: deployments/history/<vm>/<network>.json, mainnet-only retired factories for recovery.
const freeze = (value) => {
  if (value && typeof value === "object") {
    Object.freeze(value);
    for (const child of Object.values(value)) freeze(child);
  }
  return value;
};

const DATA = ${JSON.stringify(data, null, 2)};
const HISTORY_DATA = ${JSON.stringify(factoryHistory, null, 2)};

export const DEPLOYMENTS = freeze(DATA);
export const DEPLOYMENT_CHAINS = freeze(Object.keys(DATA).sort());
export const DEPLOYMENT_VMS = freeze([...new Set(Object.values(DATA).map((d) => d.vm))].sort());
export const FACTORY_HISTORY = freeze(HISTORY_DATA);

// Accept a network id, a CAIP-2, or an EVM chain id. No fallback to another network: an unknown deployment is null.
export function deploymentFor(chainOrId) {
  if (chainOrId === null || chainOrId === undefined) return null;
  const value = typeof chainOrId === "object"
    ? chainOrId.id ?? chainOrId.network ?? chainOrId.caip2
    : chainOrId;
  if (value === null || value === undefined) return null;
  if (typeof value === "number" || /^[0-9]+$/.test(String(value))) {
    return Object.values(DEPLOYMENTS).find((d) => Number(d.chainRef) === Number(value)) ?? null;
  }
  return DEPLOYMENTS[value] ?? Object.values(DEPLOYMENTS).find((d) => d.caip2 === value) ?? null;
}
`;
}

const generated = generate();
if (process.argv.includes("--check")) {
  let current = "";
  try {
    current = readFileSync(OUTPUT, "utf8");
  } catch {
    // Missing output is stale by definition.
  }
  if (current !== generated) {
    console.error("deployment pins are stale; run: node tools/gen-deployment-pins.mjs --write");
    process.exit(1);
  }
  console.log("deployment pins: current");
} else if (process.argv.includes("--write")) {
  writeFileSync(OUTPUT, generated);
  console.log(`deployment pins written: ${relative(ROOT, OUTPUT).replaceAll("\\", "/")}`);
} else {
  fail("usage: node tools/gen-deployment-pins.mjs --write | --check");
}
